from PIL import Image,ImageOps
from produce import EP,ROOT,request,save
outdir=EP/'image/character-current';ref=EP/'image/references/worker-refined-reference.png'
can=Image.new('RGB',(2400,1200),(112,120,123))
a=Image.open(ROOT/'projects/人生体验/planning/refs/主角-多角度.jpg').crop((0,0,600,600));a=ImageOps.contain(a,(800,1200));can.paste(a,((800-a.width)//2,(1200-a.height)//2))
b=ImageOps.fit(Image.open(EP/'image/backgrounds/kitchen-full.png'),(1600,1200));can.paste(b,(800,0));can.save(ref)
prompt='''Create ONE newly drawn full-body adult cleaner character in an old painted kitchen. LEFT reference: simple facial shape language, compact clothed cartoon anatomy and painted shading ONLY. RIGHT reference: existing kitchen geometry, material and daylight ONLY. Output one coherent full-frame 16:9 illustration, NO panels or reference strips. Character: bald pale grey-white rounded head, NO nose, NO hair, two SMALL BLACK VERTICAL OVAL EYES, eyes mostly solid black with at most tiny highlights; absolutely NO large circular white eyeballs, NO visible large white sclera. Thin slightly lowered concerned eyebrows, small CLOSED gently pressed mouth, calm thoughtful experienced expression, not startled or smiling. Ears tiny, close against sides of head, barely protruding simple C contours, no large lobes or internal anatomical linework; far ear mostly hidden by head in three-quarter angle. Oversized round head on compact adult cartoon body, EXACT overall proportions about THREE AND A QUARTER HEADS TALL including head, head occupies almost one third total height. Short torso, short legs, narrow gently sloped shoulders, NOT tall long-legged cartoon man, NOT normal adult anatomy, NOT cute baby mascot. Fully drawn volumetric sleeves and trousers, NO black rod limbs. Faded muted blue-grey zip work jacket with only two plain pockets, charcoal trousers, small mustard-yellow cleaning gloves and small dark practical shoes. A few broad folds only, no dense fabric wrinkle rendering. Full body and shoes visible with margin. Pose: mature cleaner inspecting dirty floor, head and eyes angled down towards clutter off to lower-left, shoulders relaxed slightly lowered, upper back mildly rounded, torso leans forward a LITTLE, knees softly bent, weight shifted naturally; one hand gently pulls snug the opposite glove cuff at waist level. Hands must have clear understandable contact, not multiple fingers or duplicated arms. Do not stand at attention or pose symmetrically for camera. Hand-drawn 2D narrative cartoon with deep grey-brown clean natural outlines, flat painted shapes plus restrained cool-grey soft shadow and soft reflected green room light, feet anchored by contact shadows. Detailed hand-painted background with sea-green tiles, dirty cabinets and sink, daylight from rear right. Do not reuse reference clothing, vehicles or background. No text, lettering, comic marks, logo, watermark, cats or extra people. Clearly fresh artwork, no pasted source pixels. Keep key facial and hand information above lower fifth.'''
src=request('worker-roundhead-refined',prompt,0,ref,dict(stage='character-refinement',cast='worker',fact='小黑椭圆眼、闭嘴、小贴耳、约3.25头身、微前倾检查地面并拉紧手套',reference_roles={str(ROOT/'projects/人生体验/planning/refs/主角-多角度.jpg'):'抽象脸部和身体画法',str(EP/'image/backgrounds/kitchen-full.png'):'厨房环境与光'}))
out=outdir/'清理垃圾屋_主角_圆头手绘_v2.png'
with Image.open(src) as im:ImageOps.fit(im.convert('RGB'),(1920,1080),method=Image.Resampling.LANCZOS).save(out)
save(EP/'qa/character-current.json',dict(file=str(out.relative_to(EP)),status='待目检',refinement='表情、耳朵、比例及体态'))
print('READY',flush=True)
